    @m.app.middleware("http")
    async def _v139_html(request, call_next):
        response = await call_next(request)
        if request.url.path != "/" or getattr(response, "status_code", 200) != 200:
            return response
        try:
            body = b""
            async for chunk in response.body_iterator:
                body += chunk
            html = body.decode("utf-8", errors="replace")
            if "v139-commercial-direct-js" not in html:
                html = html.replace("</head>", css + "</head>", 1).replace("</body>", js + "</body>", 1)
            return HTMLResponse(html, status_code=response.status_code, headers={
                "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
                "Pragma": "no-cache",
                "Expires": "0",
                "X-Operations-UI-Version": "V139-COMMERCIAL-DIRECT-DOM",
            })
        except Exception as exc:
            print(f"[V139] HTML warning: {type(exc).__name__}: {exc}", flush=True)
            return response

    m._V139_COMMERCIAL_DIRECT_DOM = True
    print("[V139] Comercial directo instalado: sin iframe ni carga diferida.", flush=True)
